const assert = require('node:assert/strict');

const { ProfileService } = require('../.build/service');
const { parseProfile } = require('../.build/parser');

const STORED = () => ({ displayName: 'before', tags: ['old'] });

function rejects(service, input) {
  assert.throws(() => service.patch(input), /invalid profile/);
}

// --- parseProfile: shape of the parsed patch -------------------------------
assert.deepEqual(parseProfile({}), { displayName: { kind: 'keep' }, tags: { kind: 'keep' } });
assert.deepEqual(
  parseProfile({ displayName: '  x  ' }),
  { displayName: { kind: 'set', value: 'x' }, tags: { kind: 'keep' } },
);
assert.deepEqual(
  parseProfile({ tags: [' a '] }),
  { displayName: { kind: 'keep' }, tags: { kind: 'set', value: ['a'] } },
);
assert.deepEqual(
  parseProfile({ displayName: null, tags: null }),
  { displayName: { kind: 'set', value: null }, tags: { kind: 'set', value: [] } },
);

// --- top-level shape -------------------------------------------------------
for (const bad of [undefined, null, 0, 42, 'str', true, Symbol('x'), () => {}, [], ['x'], new Date()]) {
  rejects(new ProfileService(STORED()), bad);
}
const instance = new (class Custom { constructor() { this.displayName = 'x'; } })();
rejects(new ProfileService(STORED()), instance);
rejects(new ProfileService(STORED()), Object.create({ inherited: 1 }));
assert.deepEqual(new ProfileService(STORED()).patch(Object.create(null)), STORED());

// --- unknown keys ----------------------------------------------------------
rejects(new ProfileService(STORED()), { unknown: 1 });
rejects(new ProfileService(STORED()), { displayName: 'x', extra: null });
rejects(new ProfileService(STORED()), { tags: ['a'], displayName: 'b', unrelated: {} });
{
  const input = Object.create(null);
  input.displayName = 'x';
  const symbol = Symbol('extra');
  input[symbol] = 1;
  rejects(new ProfileService(STORED()), input);
}

// --- displayName -----------------------------------------------------------
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ displayName: '  after  ' }), { displayName: 'after', tags: ['old'] });
  assert.deepEqual(service.patch({ displayName: '\n\t hi \n' }), { displayName: 'hi', tags: ['old'] });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ displayName: 'x'.repeat(40) }), { displayName: 'x'.repeat(40), tags: ['old'] });
  rejects(service, { displayName: 'x'.repeat(41) });
  assert.deepEqual(service.profile, { displayName: 'x'.repeat(40), tags: ['old'] });
}
for (const bad of ['', '   ', 42, 0, true, false, {}, [], ['x'], () => {}, Symbol('x'), undefined]) {
  rejects(new ProfileService(STORED()), { displayName: bad });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ displayName: null }), { displayName: null, tags: ['old'] });
  assert.deepEqual(service.patch({}), { displayName: null, tags: ['old'] });
}

// --- tags ------------------------------------------------------------------
for (const bad of [42, 'x', true, {}, () => {}, undefined]) {
  rejects(new ProfileService(STORED()), { tags: bad });
}
for (const bad of [[42], [0], [null], [undefined], [{}], [[]], [true], ['a', 7]]) {
  rejects(new ProfileService(STORED()), { tags: bad });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ tags: ['  a  ', 'b\t'] }), { displayName: 'before', tags: ['a', 'b'] });
  assert.deepEqual(service.patch({ tags: ['a'.repeat(12)] }), { displayName: 'before', tags: ['a'.repeat(12)] });
  rejects(service, { tags: ['a'.repeat(13)] });
  assert.deepEqual(service.profile, { displayName: 'before', tags: ['a'.repeat(12)] });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ tags: ['1', '2', '3', '4', '5'] }), { displayName: 'before', tags: ['1', '2', '3', '4', '5'] });
  rejects(service, { tags: ['1', '2', '3', '4', '5', '6'] });
  assert.deepEqual(service.profile, { displayName: 'before', tags: ['1', '2', '3', '4', '5'] });
}
for (const bad of [['a', 'a'], ['a ', ' a'], ['a', 'a', 'b'], [''], ['   '], ['a', ''], ['a', '   ']]) {
  rejects(new ProfileService(STORED()), { tags: bad });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ tags: ['a', 'A'] }), { displayName: 'before', tags: ['a', 'A'] });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ tags: null }), { displayName: 'before', tags: [] });
  assert.deepEqual(service.profile.tags, []);
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ tags: [] }), { displayName: 'before', tags: [] });
}
{
  const service = new ProfileService(STORED());
  assert.deepEqual(service.patch({ displayName: null, tags: null }), { displayName: null, tags: [] });
}

// --- failure atomicity -----------------------------------------------------
{
  const service = new ProfileService(STORED());
  rejects(service, { displayName: 'valid', tags: ['a', 'a'] });
  assert.deepEqual(service.profile, STORED());
  rejects(service, { displayName: 'second', tags: 'nope' });
  assert.deepEqual(service.profile, STORED());
  rejects(service, { extra: 1 });
  assert.deepEqual(service.profile, STORED());
  service.patch({ displayName: 'first' });
  rejects(service, { displayName: null, tags: [42] });
  assert.deepEqual(service.profile, { displayName: 'first', tags: ['old'] });
  service.patch({ tags: [] });
  rejects(service, { displayName: 42 });
  assert.deepEqual(service.profile, { displayName: 'first', tags: [] });
}

// --- empty object is a no-op ----------------------------------------------
{
  const stored = STORED();
  const service = new ProfileService(stored);
  const returned = service.patch({});
  assert.equal(returned, stored);
  assert.equal(returned.tags, stored.tags);
  assert.deepEqual(returned, STORED());
}

// --- caller input untouched ----------------------------------------------
{
  const input = { displayName: ' a ', tags: [' b '] };
  const before = JSON.stringify(input);
  new ProfileService(STORED()).patch(input);
  assert.equal(JSON.stringify(input), before);
}

// --- storage must not alias the caller's tags array ----------------------
{
  const callerTags = [' x '];
  const stored = STORED();
  const returned = new ProfileService(stored).patch({ tags: callerTags });
  assert.notEqual(returned.tags, callerTags);
  assert.deepEqual(returned.tags, ['x']);
  callerTags.push('evil');
  assert.deepEqual(returned.tags, ['x']);
  assert.deepEqual(stored.tags, ['x']);
}
{
  const callerTags = [];
  const stored = STORED();
  const returned = new ProfileService(stored).patch({ tags: callerTags });
  assert.notEqual(returned.tags, callerTags);
  assert.deepEqual(returned.tags, []);
  callerTags.push('evil');
  assert.deepEqual(returned.tags, []);
}

// --- trimming stored values ----------------------------------------------
{
  const service = new ProfileService({ displayName: '  ', tags: [' x ', ' y '] });
  const returned = service.patch({});
  assert.deepEqual(returned, { displayName: '  ', tags: [' x ', ' y '] });
  const updated = service.patch({ displayName: ' Name ', tags: [' A ', ' B '] });
  assert.deepEqual(updated, { displayName: 'Name', tags: ['A', 'B'] });
}

console.log('checks/patch.cjs: all assertions passed');

